using System.Threading;using System.Runtime.InteropServices;using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;using System.IO.Compression;using System.Diagnostics;
namespace Glint {
sealed class ToolServices {
 internal string TestOutput {get;set;}
 internal Action<string,long,long> Progress;internal Action<string> OpenOutput;
 void Report(string phase,long done,long total){if(Progress!=null)Progress(phase,done,total);}
 object Output(string path){RecentStore.Record(path);return new{saved=true,file=path,name=Path.GetFileName(path),token=Add(path),bytes=new FileInfo(path).Length};}
 CancellationTokenSource speechCancel;
 readonly Dictionary<string,string> files=new Dictionary<string,string>();
 static string S(Dictionary<string,object> d,string k){return d.ContainsKey(k)?Convert.ToString(d[k]):"";}
 public string Add(string path){string token=Guid.NewGuid().ToString("N");files[token]=Path.GetFullPath(path);return token;}
 public object Packet(string path){if(new FileInfo(path).Length>128*1024*1024)throw new IOException("文件超过 128 MB，请选择较小文件。");return new{token=Add(path),name=Path.GetFileName(path),base64=Convert.ToBase64String(File.ReadAllBytes(path))};}
 string PathFor(Dictionary<string,object> d){string p;if(!files.TryGetValue(S(d,"token"),out p))throw new IOException("请先选择文件。");return p;}
 public async Task<object> Handle(Form owner,Dictionary<string,object> d){string cmd=S(d,"command");
 if(cmd=="toolSpeechStatus")return new{ready=SpeechToText.Ready,bytes=190085487};
 if(cmd=="toolSpeechCancel"){if(speechCancel!=null)speechCancel.Cancel();return true;}
 if(cmd=="toolTranscribe"){if(speechCancel!=null)throw new IOException("已有识别任务正在进行。");string source=PathFor(d);using(var cancellation=new CancellationTokenSource()){speechCancel=cancellation;try{return await Task.Run(()=>SpeechToText.Extract(source,S(d,"language"),S(d,"preferSubtitles")!="no",Report,cancellation.Token));}catch(OperationCanceledException){throw new IOException("已取消识别。");}finally{speechCancel=null;}}}
 if(cmd=="toolDownload"){Report("正在解析公开链接…",0,-1);var info=await LinkDownload.ParseAsync(owner,S(d,"url"));string target=TestOutput;if(target==null){Report("解析成功，请选择保存文件夹",0,-1);using(var folder=new FolderBrowserDialog{Description="选择视频保存文件夹"}){if(folder.ShowDialog(owner)!=DialogResult.OK)return false;target=folder.SelectedPath;}}string saved=await Task.Run(()=>LinkDownload.Download(info,target,(done,total)=>Report("正在下载视频",done,total)));return Output(saved);}
 if(cmd=="toolOpenOutput"){if(OpenOutput!=null)OpenOutput(PathFor(d));return true;}
 if(cmd=="toolRevealOutput"){Process.Start(new ProcessStartInfo("explorer.exe","/select,\""+PathFor(d)+"\""){UseShellExecute=true});return true;}
 if(cmd=="toolBundle"){using(var ms=new MemoryStream()){using(var zip=new ZipArchive(ms,ZipArchiveMode.Create,true)){var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var item in (System.Collections.IEnumerable)d["items"]){var file=(Dictionary<string,object>)item;string name=Path.GetFileName(S(file,"name"));if(!names.Add(name))throw new IOException("存在同名输出，请分批处理");var e=zip.CreateEntry(name);using(var output=e.Open()){byte[] bytes=Convert.FromBase64String(S(file,"base64"));output.Write(bytes,0,bytes.Length);}}}return Convert.ToBase64String(ms.ToArray());}}
 if(cmd=="toolPick"){using(var dialog=new OpenFileDialog{Multiselect=true,Filter="所有文件|*.*"}){if(dialog.ShowDialog(owner)!=DialogResult.OK)return null;return dialog.FileNames.Select(p=>S(d,"metadata")=="yes"?(object)new{token=Add(p),name=Path.GetFileName(p)}:Packet(p)).ToArray();}}
 if(cmd=="toolSave"){string ext=S(d,"extension").TrimStart('.');if(!new[]{"pdf","png","jpg","webp","bmp","zip","txt","md","json","srt","vtt","mp4","mp3","m4a","wav"}.Contains(ext))throw new IOException("不支持的保存格式");using(var dialog=new SaveFileDialog{FileName=Path.GetFileName(S(d,"name")),Filter=ext.ToUpperInvariant()+"|*."+ext,DefaultExt=ext,AddExtension=true,OverwritePrompt=true}){if(TestOutput!=null){Directory.CreateDirectory(TestOutput);dialog.FileName=Path.Combine(TestOutput,Path.GetFileName(S(d,"name")));}else if(dialog.ShowDialog(owner)!=DialogResult.OK)return false;byte[] bytes=Convert.FromBase64String(S(d,"base64"));string temp=dialog.FileName+"."+Guid.NewGuid().ToString("N")+".tmp";try{await Task.Run(()=>File.WriteAllBytes(temp,bytes));if(File.Exists(dialog.FileName))File.Replace(temp,dialog.FileName,null);else File.Move(temp,dialog.FileName);}finally{if(File.Exists(temp))File.Delete(temp);}return Output(dialog.FileName);}}
 if(cmd=="toolOCR"){byte[] bytes=Convert.FromBase64String(S(d,"base64"));return await Task.Run(()=>Recognize(bytes));}
 if(cmd=="toolZipList"){using(var zip=ZipFile.OpenRead(PathFor(d)))return zip.Entries.Select(e=>new{name=e.FullName,size=e.Length}).ToArray();}
 if(cmd=="toolZipRead"){using(var zip=ZipFile.OpenRead(PathFor(d))){var e=zip.GetEntry(S(d,"entry"));if(e==null||e.Length>16*1024*1024)throw new IOException("预览限 16 MB");using(var ms=new MemoryStream()){using(var input=e.Open())input.CopyTo(ms);return new{name=e.Name,base64=Convert.ToBase64String(ms.ToArray())};}}}
 if(cmd=="toolZipExtract"){using(var dialog=new FolderBrowserDialog{Description="选择解压父目录，将新建独立文件夹"}){if(dialog.ShowDialog(owner)!=DialogResult.OK)return null;string destination=Path.Combine(dialog.SelectedPath,Path.GetFileNameWithoutExtension(PathFor(d))+"-"+DateTime.Now.ToString("yyyyMMddHHmmss"));return await Task.Run(()=>{ExtractZip(PathFor(d),destination);return destination;});}}
 if(cmd=="toolZipCreate"){using(var pick=new OpenFileDialog{Multiselect=true,Title="选择要打包的文件"}){if(pick.ShowDialog(owner)!=DialogResult.OK)return false;using(var save=new SaveFileDialog{Filter="ZIP|*.zip",DefaultExt="zip",FileName="打包.zip",OverwritePrompt=true}){if(save.ShowDialog(owner)!=DialogResult.OK)return false;string[] source=pick.FileNames;string target=save.FileName;return await Task.Run(()=>{CreateZip(source,target);return true;});}}}
 if(cmd=="toolMediaExport"){string source=PathFor(d),format=S(d,"format");if(!new[]{"mp4","mp3","m4a","wav"}.Contains(format))throw new IOException("不支持的导出格式");double start,end;if(!double.TryParse(S(d,"start"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out start)||!double.TryParse(S(d,"end"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out end)||start<0||end<=start)throw new IOException("请输入有效的开始和结束秒数");using(var save=new SaveFileDialog{Filter=format+"|*."+format,DefaultExt=format,FileName=Path.GetFileNameWithoutExtension(source)+"-片段."+format,OverwritePrompt=true}){if(save.ShowDialog(owner)!=DialogResult.OK)return false;if(string.Equals(source,save.FileName,StringComparison.OrdinalIgnoreCase))throw new IOException("请另存为新文件。");string output=save.FileName;await Task.Run(()=>ExportMedia(source,output,format,start,end));return Output(output);}}
 throw new IOException("未知工具操作");}
 public static string Recognize(byte[] bytes){string temp=Path.Combine(Path.GetTempPath(),"glint-ocr-"+Guid.NewGuid().ToString("N")),image=temp+".png",result=temp+".txt";try{File.WriteAllBytes(image,bytes);string helper=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"helpers","ocr.ps1");using(var p=Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32","WindowsPowerShell","v1.0","powershell.exe"),"-NoProfile -ExecutionPolicy Bypass -File \""+helper+"\" -ImagePath \""+image+"\" -OutputPath \""+result+"\""){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(120000)){p.Kill();throw new IOException("识别超时");}if(p.ExitCode!=0)throw new IOException(File.Exists(result+".error")?File.ReadAllText(result+".error"):"系统文字识别不可用");}return File.ReadAllText(result);}finally{foreach(string path in new[]{image,result,result+".error"})if(File.Exists(path))File.Delete(path);}}
 public static void CreateZip(string[] source,string target){string temp=target+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var zip=ZipFile.Open(temp,ZipArchiveMode.Create)){var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string file in source){string name=Path.GetFileName(file);if(!names.Add(name))throw new IOException("存在同名文件，请分别打包。");zip.CreateEntryFromFile(file,name,CompressionLevel.Optimal);}}if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static void ExtractZip(string source,string destination){if(Directory.Exists(destination))throw new IOException("目标目录已经存在");using(var zip=ZipFile.OpenRead(source)){string root=Path.GetFullPath(destination).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;long size=0;foreach(var e in zip.Entries){string full=Path.GetFullPath(Path.Combine(root,e.FullName));if(!full.StartsWith(root,StringComparison.OrdinalIgnoreCase)||e.FullName.Contains(":"))throw new IOException("压缩包包含无效路径");size+=e.Length;if(size>2L*1024*1024*1024)throw new IOException("解压内容超过 2 GB");}Directory.CreateDirectory(destination);foreach(var e in zip.Entries){string full=Path.GetFullPath(Path.Combine(root,e.FullName));if(e.Name.Length==0){Directory.CreateDirectory(full);continue;}Directory.CreateDirectory(Path.GetDirectoryName(full));e.ExtractToFile(full,false);}}}
 public static void ExportMedia(string source,string destination,string format,double start,double end){string temp=destination+"."+Guid.NewGuid().ToString("N")+".tmp";bool audio=format!="mp4";var options=new Dictionary<string,string>{{"config","no"},{"terminal","no"},{"idle","yes"},{"keep-open","no"},{"o",temp},{"of",format=="m4a"?"mp4":format},{"start",start.ToString(System.Globalization.CultureInfo.InvariantCulture)},{"length",(end-start).ToString(System.Globalization.CultureInfo.InvariantCulture)},{"oac",format=="mp3"?"libmp3lame":format=="wav"?"pcm_s16le":"aac"}};if(audio)options["vid"]="no";else{options["ovc"]="libx264";options["ovcopts"]="preset=veryfast,crf=21";options["vf"]="lavfi=[format=yuv420p,pad=ceil(iw/2)*2:ceil(ih/2)*2]";}try{using(var engine=new Engine(options)){engine.Command("loadfile",source,"replace");while(true){IntPtr e=Native.mpv_wait_event(engine.Handle,.1);if(System.Runtime.InteropServices.Marshal.ReadInt32(e)==7){IntPtr data=Marshal.ReadIntPtr(e,16);int reason=Marshal.ReadInt32(data);if(reason!=0)throw new IOException("片段导出失败或源文件无法解码");break;}}}if(!File.Exists(temp)||new FileInfo(temp).Length<64)throw new IOException("未生成有效文件");if(File.Exists(destination))File.Replace(temp,destination,null);else File.Move(temp,destination);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
}
